use filmcraft_render::{image::Image,blend::{Blend,composite_at}};use serde_json::json;
fn image(w:usize,h:usize,variant:usize,side:usize)->Image{let mut image=Image::new(w,h);let values=[0.,0.003,0.04,0.25,0.5,0.75,1.];for (i,p)in image.px.chunks_exact_mut(4).enumerate(){let alpha=[0.,0.25,0.7,1.][(i+variant+side)%4];for c in 0..3{p[c]=values[(i*3+c+variant*5+side)%values.len()]*alpha;}p[3]=alpha;}image}
fn wire(image:&Image)->serde_json::Value{json!({"w":image.w,"h":image.h,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()})}
fn main(){let catalog:serde_json::Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let mut cases=vec![];let base=image(8,4,0,0);let a=image(8,4,1,0);let b=image(8,4,2,1);
for mode in 0..27{for opacity in [0.,0.37,1.]{let mut out=base.clone();composite_at(&mut out,&a,0,0,opacity,Blend::from_index(mode));cases.push(json!({"kind":"clip","mode":mode,"opacity":opacity,"bits":wire(&out)["bits"]}));}}
for entry in catalog.as_array().unwrap().iter().filter(|e|e["definition"]["kind"]=="VideoTransition"){let effect:filmcraft_project::EffectInstance=serde_json::from_value(entry["instance"].clone()).unwrap();for progress in [0.,0.37,1.]{for reverse in [false,true]{let mut la=a.clone();let mut lb=b.clone();for v in &mut la.px{*v*=0.37}for v in &mut lb.px{*v*=0.73}let mixed=if reverse{filmcraft_render::transitions::apply_scaled(&effect,&lb,&la,1.-progress,1.)}else{filmcraft_render::transitions::apply_scaled(&effect,&la,&lb,progress,1.)};let mut out=base.clone();composite_at(&mut out,&mixed,0,0,1.,Blend::Normal);cases.push(json!({"kind":"transition","effect":effect,"progress":progress,"reverse":reverse,"bits":wire(&out)["bits"]}));}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","base":wire(&base)["bits"],"a":wire(&a)["bits"],"b":wire(&b)["bits"],"cases":cases}));}
